	ll flow = 0,  cost = 0;
	while (flow < k) {
		// cout<<flow<<"A";
		vector<ll> id (n, 0);
		vector<ll> d (n, INF);
		vector<ll> q (n);
		vector<ll> p (n);
		vector<size_t> p_rib (n);
		ll qh=0, qt=0;
