int main()
{
  scanf("%d%d%d%d%d",&n,&m,&k,&C,&D);
  S=P(n+k,n)+1;T=S+2;
  adl(P(0,1),T,INF,0);
  for (int i=1,p;i<=k;i++){
    scanf("%d",&p);
    adl(S,P(0,p),1,0);
  }for (int i=1;i<=m;i++){
    scanf("%d%d",&s[i*2].f,&s[i*2].t);
    s[i*2-1]=(Data){s[i*2].t,s[i*2].f};
  }m*=2;
  for (int t=1;t<=n+k;t++){
    for (int i=1;i<=n;i++)
      adl(P(t-1,i),P(t,i),INF,0);
    for (int i=1;i<=m;i++){
      adl(P(t-1,s[i].f),P(t,s[i].t),1,D);
      pl[t][i]=tl;st[t][i]=1;
    }adl(P(t,1),T,INF,t*C);
  }
  int sav,cans=0;
  while(sav=spfa()){
    int u=T;
    while(u!=S){
      int las=pre[u];
      g[lp[u]].c-=sav;
      g[lp[u]^1].c+=sav;
      u=las;
    }cans+=dis[T]*sav;
    for (int t=1;t<=n+n;t++)
      for (int i=1;i<=m;i++)
        if (g[pl[t][i]].c){
          st[t][i]++;
          adl(P(t-1,s[i].f),P(t,s[i].t),1,D*(st[t][i]*2-1));
          pl[t][i]=tl;
        }
  }printf("%d\n",cans);
  return 0;
}

