void dijkstra()
{
    fill(dis, dis + MX, INF);
    pq.push({dis[s] = 0, s});
    while (!pq.empty())
    {
        pair<long long, int> u = pq.top();
        pq.pop();
        if (u.fi > dis[u.se])
            continue;
        for (SEdge &ed : adj[u.se])
        {
            if (ed.cap > 0 && dis[ed.v] > u.fi + ed.c)
            {
                tr[ed.v] = ed.ind;
                pq.push({dis[ed.v] = u.fi + ed.c, ed.v});
            }
        }
    }
}

void trace()
{
    int mx = k, v = t;
    while (v != s)
    {
        int u = adj[v][tr[v]].v, ind = adj[v][tr[v]].ind;
        mx = min(mx, adj[u][ind].cap);
        v = u;
    }
    mf += mx; ans += mx * dis[t];
    v = t;
    while (v != s)
    {
        int u = adj[v][tr[v]].v, ind = adj[v][tr[v]].ind;
        adj[v][tr[v]].cap += mx;
        adj[u][ind].cap -= mx;
        v = u;
    }
