using namespace std;
const int N = 10000010, INF = 0x3f3f3f3f;
int n, m, c, d, k, s = 0, t, ans = 0;
int cnt = 1, hed[N], to[N], nxt[N], val[N], w[N];
int dis[N], incf[N], pre[N]; bool inq[N];

void add(int x, int y, int z, int v) {
	to[++cnt] = y, nxt[cnt] = hed[x], hed[x] = cnt, val[cnt] = z, w[cnt] = v;
	to[++cnt] = x, nxt[cnt] = hed[y], hed[y] = cnt, val[cnt] = 0, w[cnt] = -v;
}
bool spfa() {
	memset(incf, 0, sizeof(incf)), memset(dis, INF, sizeof(dis));
	memset(inq, 0, sizeof(inq)); queue<int> q;
	q.push(s), incf[s] = INF, inq[s] = 1, dis[s] = 0;
	for(; !q.empty();) {
		int u = q.front(); q.pop(); inq[u] = 0;
		for(int i = hed[u]; i; i = nxt[i]) {
			if(!val[i] || dis[to[i]] <= dis[u] + w[i]) continue;
			dis[to[i]] = dis[u] + w[i];
			incf[to[i]] = min(incf[u], val[i]);
			pre[to[i]] = i; if(!inq[to[i]]) inq[to[i]] = 1, q.push(to[i]);
		}
	}
	return dis[t] != INF;
}
void update() {
	int tmp = t;
	for(; tmp != s;) {
		int i = pre[tmp];
		val[i] -= incf[t], val[i ^ 1] += incf[t], tmp = to[i ^ 1];
	}
	ans += incf[t] * dis[t];
}
int main() {
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d), t = (n + k - 1) * n + 1;
	for(int i = 1, x; i <= k; i++) scanf("%d", &x), add(s, x, 1, 0);
	for(int i = 1, x, y; i <= m; i++) {
		scanf("%d%d", &x, &y);
		for(int j = 1; j <= n + k; j++)
			for(int h = 1; h <= k; h++) {
				add(x + (j - 1) * n, y + j * n, 1, d * h * 2 - d + c);
				add(y + (j - 1) * n, x + j * n, 1, d * h * 2 - d + c);
			}
	}
	for(int i = 1; i < n + k; i++) {
		for(int j = 2; j <= n; j++)
			add(j + (i - 1) * n, j + i * n, INF, c);
		add(1 + (i - 1) * n, 1 + i * n, INF, 0);
	}
	for(; spfa();) update();
	printf("%d\n", ans);
	return 0;
}

#include <bits/stdc++.h>
#define db(x) cout << (x) << '\n';
using namespace std;
typedef long long ll;
typedef pair<ll,ll> pii;
typedef pair<ll,pii> pip;
typedef pair<pii,pii> ppp;
typedef long double ld;
#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>
using namespace __gnu_pbds;

typedef tree<ll, null_type, less<ll>,rb_tree_tag, tree_order_statistics_node_update> ordered_set;

/*
    Minimum Cost Flow (Tomizawa, Edmonds-Karp)
    Complexity:
    O(F m log n), where F is the amount of maximum flow
    Tested:
    Codeforces [http://codeforces.com/problemset/problem/717/G]
*/
template<typename flow_type, typename cost_type>
struct min_cost_max_flow
{
    struct edge
    {
        size_t src, dst, rev;
        flow_type flow, cap;
        cost_type cost;
    };
    int n;
    vector<vector<edge>> adj;
    min_cost_max_flow(int n) : n(n), adj(n), potential(n), dist(n), back(n) {}
    void add_edge(size_t src, size_t dst, flow_type cap, cost_type cost)
    {
        adj[src].push_back({src, dst, adj[dst].size(), 0, cap, cost});
        if (src == dst)
            adj[src].back().rev++;
        adj[dst].push_back({dst, src, adj[src].size() - 1, 0, 0, -cost});
    }
    vector<cost_type> potential;
    inline cost_type rcost(const edge &e)
    {
        return e.cost + potential[e.src] - potential[e.dst];
    }

//    void bellman_ford(int source)
//    {
//        for (int k = 0; k < n; ++k)
//            for (int u = 0; u < n; ++u)
//                for (edge &e : adj[u])
//                    if (e.cap > 0 && rcost(e) < 0)
//                        potential[e.dst] += rcost(e);
//    }
    const cost_type oo = numeric_limits<cost_type>::max();
    vector<cost_type> dist;
    vector<edge * > back;
    cost_type dijkstra(int source, int sink)
    {
        fill(dist.begin(), dist.end(), oo);
        typedef pair<cost_type, int> node;
        priority_queue<node, vector<node>, greater<node>> pq;
        for (pq.push({dist[source] = 0, source}); !pq.empty();)
        {
            node p = pq.top();
            pq.pop();
            if (dist[p.second] < p.first)
                continue;
            if (p.second == sink)
                break;
            for (edge &e : adj[p.second])
                if (e.flow < e.cap &&
                        dist[e.dst] > dist[e.src] + rcost(e))
                {
                    back[e.dst] = &e;
                    pq.push({
                        dist[e.dst] = dist[e.src] + rcost(e),
                        e.dst
                    });
                }
        }
        return dist[sink];
    }
    pair<flow_type, cost_type> max_flow(int source, int sink)
    {
        flow_type flow = 0;
        cost_type cost = 0;
        for (int u = 0; u < n; ++u)
            for (edge &e : adj[u])
                e.flow = 0;
        potential.assign(n, 0);
        dist.assign(n, 0);
        back.assign(n, nullptr);
//        bellman_ford(source); // remove negative costs
        while (dijkstra(source, sink) < oo)
        {
            for (int u = 0; u < n; ++u)
            if (dist[u] < dist[sink])
                potential[u] += dist[u] - dist[sink];
            flow_type f = numeric_limits<flow_type>::max();
            for (edge * e = back[sink]; e; e = back[e->src])
                f = min(f, e->cap - e->flow);
            for (edge * e = back[sink]; e; e = back[e->src])
                e->flow += f, adj[e->dst][e->rev].flow -= f;
            flow += f;
            cost += f * (potential[sink] - potential[source]);
        }
        return {flow, cost};
    }
};

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

