struct dsu {
	vi r, p;
	void init(int n) {
		r.resize(n);
		p.resize(n);
		for(int i = 0; i < n; i++) p[i] = i, r[i] = 1;
	}
	int par(int i) {
		if(i == p[i]) return i;
		return p[i] = par(p[i]);
	}
	void unite(int i, int j) {
		i = par(i), j = par(j);
		if(i==j) return;
		if(r[i] < r[j]) swap(i, j);
		p[j] = i;
		r[i] += r[j];
	} 
};
int n, k;
dsu d;
ll pw(ll x, ll p, ll M) {
	ll r = 1;
	while(p--) r = (r*1ll*x)%M;
	return r;
}
