		d.unite(i, (i*1ll*k)%n);
	}
	ll ans = 1;
	for(int i = 0; i < n; i++) {
		if(d.par(i)!=i) continue;
		ll t = pw(k, d.r[i], n);
		if(t==1) {
			ans = (ans*1ll*n)%mod;
		}	
	}
	cout << ans << '\n';
}

