{
    vector<int> parent;
    vector<int> cont;
    int cc;
    DS(int n) : parent(n), cont(n, 1), cc(0)
    {
        for(int i=0; i<n; i++)
            parent[i] = i;
    }
    int SetOf(int x)
    {
        return parent[x] = (parent[x] == x ? x : SetOf(parent[x]));
    }
    bool Merge(int x, int y)
    {
        x = SetOf(x);
        y = SetOf(y);
        if(x == y) return false;
