void solve(int A, int B, int* vis, bool check)
{
	queue<pair<int, int> > que;
	vis[A*n+B] = 0;
	que.push(mp(A, B));
	while (!que.empty())
	{
		pair<int, int> now = que.front();
		que.pop();
		int p = now.F*n+now.S;
		int dis = vis[p];
		if (check && (mat[bi*n+bj][p] <= dis || t <= dis))
		{
			if (mat[bi*n+bj][p] < dis || t < dis) vis[p] = INF+1;
			continue;
		}
		for (int d = 0; d < 4; ++d)
		{
			int i = dir[d][0]+now.F;
			int j = dir[d][1]+now.S;
			if (i < 0 || j < 0 || i == n || j == n) continue;
			if (b[i][j] < '0' || b[i][j] > '9') continue;
			int q = i*n+j;
			if (vis[q] != INF) continue;
			vis[q] = dis+1;
			que.push(mp(i, j));
		}
	}
}

void build()
{
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (b[i][j] <= '0' || b[i][j] > '9') continue;
			ca.push_back(i);
			cb.push_back(j);
			int p = i*n+j;
			cap[p+2+n*n][1] = b[i][j]-'0';	
		}
	}
	int z = bi*n+bj;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (a[i][j] <= '0' || a[i][j] > '9') continue;
			int p = i*n+j;
			cap[0][p+2] = a[i][j]-'0';
			for (int k = 0; k < ca.size(); ++k)
			{
				int ii = ca[k];
				int jj = cb[k];
				int q = ii*n+jj;
				if (mat[p][q] < INF)
					cap[p+2][q+2+n*n] = INF;
			}
		}
	}
}

