int get_path()
{
	vector <int> parent(counter+1,-1);
	parent[0]=0;
	stack <int> dfs;
	dfs.push(0);
	while(!dfs.empty())
	{
		int top=dfs.top();
		dfs.pop();
		if(top==counter)
			break;
		for (int i = 0; i <= counter; ++i)
		{
			if(flo[top][i] && parent[i]==-1)
			{
				parent[i]=top;
				dfs.push(i);
			}
		}
	}
	if(parent[counter]==-1)
		return 0;
	int ans=10000,pos=counter;
	while(pos!=0)
	{
		ans=min(ans,flo[parent[pos]][pos]);
		pos=parent[pos];
	}
	pos=counter;
	while(pos!=0)
	{
		flo[parent[pos]][pos]-=ans;
		flo[pos][parent[pos]]+=ans;
		pos=parent[pos];
	}
	return ans;
}
