using namespace std;

typedef pair <int, int> ii;

const int Inf = 1000000000;
const int Maxn = 11;
const int MaxN = 205;
const int Maxd = 4;
const int dy[Maxd] = {-1, 0, 1, 0};
const int dx[Maxd] = {0, -1, 0, 1};

int n, t;
char a[Maxn][Maxn], b[Maxn][Maxn];
int br, bc;
int bum[Maxn][Maxn];
int dist[Maxn][Maxn];
bool pos[Maxn][Maxn];
int N;
int R[MaxN][MaxN];
vector <int> neigh[MaxN];
int F[MaxN], P[MaxN];
int res;

void BFS1()
{
	fill((int*)bum, (int*)bum + Maxn * Maxn, t); bum[br][bc] = 0;
	queue <ii> Q; Q.push(ii(br, bc));
	while (!Q.empty()) {
		ii v = Q.front(); int d = bum[v.first][v.second]; Q.pop();
		for (int i = 0; i < Maxd; i++) {
			ii u = ii(v.first + dy[i], v.second + dx[i]);
			if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && a[u.first][u.second] != 'Y' && d + 1 < bum[u.first][u.second])
				bum[u.first][u.second] = d + 1, Q.push(u);
		}
	}
}

void BFS2(int sr, int sc)
{
	fill((int*)dist, (int*)dist + Maxn * Maxn, Inf); dist[sr][sc] = 0;
	fill((bool*)pos, (bool*)pos + Maxn * Maxn, false); pos[sr][sc] = true;
	queue <ii> Q; Q.push(ii(sr, sc));
	while (!Q.empty()) {
		ii v = Q.front(); int d = dist[v.first][v.second]; Q.pop();
		pos[v.first][v.second] = d <= bum[v.first][v.second];
		if (d >= bum[v.first][v.second]) continue;
		for (int i = 0; i < Maxd; i++) {
			ii u = ii(v.first + dy[i], v.second + dx[i]);
			if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && a[u.first][u.second] != 'Y' && d + 1 < dist[u.first][u.second])
				dist[u.first][u.second] = d + 1, Q.push(u);
		}
	}
}

void BFS(int sr, int sc, int dist[][Maxn], int Inf)
{
	fill((int*)dist, (int*)dist + Maxn * Maxn, Inf); dist[sr][sc] = 0;
	queue <ii> Q; Q.push(ii(sr, sc));
	while (!Q.empty()) {
		ii v = Q.front(); int d = dist[v.first][v.second]; Q.pop();
		for (int i = 0; i < Maxd; i++) {
			ii u = ii(v.first + dy[i], v.second + dx[i]);
			if (0 <= u.first && u.first < n && 0 <= u.second && u.second < n && a[u.first][u.second] != 'Y' && d + 1 < dist[u.first][u.second])
				dist[u.first][u.second] = d + 1, Q.push(u);
		}
	}
}

int getFlow()
{
	fill(F, F + N, 0); F[0] = Inf;
	priority_queue <ii> Q; Q.push(ii(Inf, 0));
	while (!Q.empty()) {
		int v = Q.top().second, f = Q.top().first; Q.pop();
		if (F[v] != f) continue;
		for (int i = 0; i < neigh[v].size(); i++) {
			int u = neigh[v][i];
			if (min(f, R[v][u]) > F[u]) F[u] = min(f, R[v][u]), P[u] = v, Q.push(ii(F[u], u));
		}
	}
	int v = N - 1;
	if (F[v] == 0) return 0;
	int res = F[v];
	while (v) {
		int u = P[v];
		R[u][v] -= res; R[v][u] += res;
		v = u;
	}
	return res;
}

int main()
{
	scanf("%d %d", &n, &t);
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++) {
			scanf(" %c", &a[i][j]);
			if (a[i][j] == 'Z') { br = i; bc = j; }
		}
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++)
			scanf(" %c", &b[i][j]);
	BFS1();
	N = 2 * n * n + 2;
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++) if (isdigit(a[i][j]) && a[i][j] > '0') {
			int v = i * n + j + 1; R[0][v] = a[i][j] - '0'; neigh[0].push_back(v); neigh[v].push_back(0);
			BFS2(i, j);
			for (int i2 = 0; i2 < n; i2++)
				for (int j2 = 0; j2 < n; j2++) if (pos[i2][j2] && isdigit(b[i2][j2]) && b[i2][j2] > '0') {
					int u = n * n + i2 * n + j2 + 1; R[v][u] = Inf; neigh[v].push_back(u); neigh[u].push_back(v);
				}
		}
	for (int i = 0; i < n; i++)
		for (int j = 0; j < n; j++) if (isdigit(b[i][j]) && b[i][j] > '0') {
			int u = n * n + i * n + j + 1; R[u][N - 1] = b[i][j] - '0'; neigh[u].push_back(N - 1); neigh[N - 1].push_back(u);
		}
	int f;
	while ((f = getFlow()) != 0) res += f;
	printf("%d\n", res);
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

typedef pair<int,int> par;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int oo = (1<<29);

int ady[2*MAXM], flow[2*MAXM], cap[2*MAXM], nxt[2*MAXM];
int last[MAXN], now[MAXN], lev[MAXN], cola[MAXN];
int E, n, s, t, enq, deq;

void init_maxflow( int nn, int ss, int tt ){
    n = nn; s = ss; t = tt; E = 2;
    for( int i = 0; i <= n; i++ ) last[i] = 0;

    //cerr << "n = " << n << "  s = " << s << "  t = " << t << '\n';
}
void add_edge( int u, int v, int c ){
    ady[E] = v; flow[E] = 0; cap[E] = c; nxt[E] = last[u]; last[u] = E++;
    ady[E] = u; flow[E] = 0; cap[E] = 0; nxt[E] = last[v]; last[v] = E++;

    //cerr << "u = " << u << "  -->  v = " << v << "  cap = " << c << '\n';
}
bool bfs(){
    for( int u = 0; u <= n; u++ ) lev[u] = 0;
    enq = deq = 0;
    cola[enq++] = s;
    lev[s] = 1;
    while( deq < enq && !lev[t] ){
        int u = cola[deq++];
        for( int e = last[u]; e; e = nxt[e] ){
            int v = ady[e];
            if( !lev[v] && flow[e] < cap[e] ){
                lev[v] = lev[u] + 1;
                cola[enq++] = v;
            }
        }
    }
    return lev[t];
}
int dfs( int u, int F ){
    if( u == t ) return F;
    for( int e = now[u], f = 0; e; e = now[u] = nxt[e] ){
        int v = ady[e];
        if( lev[u] < lev[v] && flow[e] < cap[e] &&
            (f = dfs( v , min( F , cap[e] - flow[e] ) )) ){
            flow[e] += f;
            flow[e^1] -= f;
            return f;
        }
    }
    return 0;
}
int max_flow(){
    int F = 0, f = 0;
    while( bfs() ){
        for( int i = 0; i <= n; i++ ) now[i] = last[i];
        while( (f = dfs( s , oo )) ) F += f;
    }
    return F;
}

int R;
string m1[MAXR];
string m2[MAXR];

int movI[] = { 0 , 1 , 0 , -1 };
int movJ[] = { 1 , 0 , -1 , 0 };

bool can_move( int i, int j ){
    return ( i >= 0 && j >= 0 && i < R && j < R && m1[i][j] != 'Y' && m1[i][j] != 'Z' );
}

int tim[2][MAXR][MAXR];

void bfs2( int i, int j, int cc ){
    for( int k = 0; k < R; k++ ){
        for( int l = 0; l < R; l++ ){
            tim[cc][k][l] = 0;
        }
    }

    tim[cc][i][j] = 1;
    queue<par> q;
    q.push( par( i , j ) );
    while( !q.empty() ){
        int i = q.front().first;
        int j = q.front().second;
        q.pop();

        if( cc == 1 && (tim[0][i][j] && tim[0][i][j] <= tim[1][i][j]) ){
            continue;
        }

        for( int k = 0; k < 4; k++ ){
            int ii = i + movI[k];
            int jj = j + movJ[k];

            if( can_move( ii , jj ) && !tim[cc][ii][jj] ){
                tim[cc][ii][jj] = tim[cc][i][j] + 1;
                q.push( par( ii , jj ) );
            }
        }
    }
}

