	int flow = 0;

	parent[0] = -1;
	do{	
		ans += flow;

		REP( i, M ) vis[i] = false;
		flow = augment(0);

		if (!flow) return ans;

		int v = 1;
		while( v != 0 ){
			int u = parent[v];
			cap[u][v] -= flow;
			cap[v][u] += flow;
			v = u;
		}
	} while( flow );

	return ans;
}

