        dist[p.first.first][p.first.second] = p.second;
        for (i = 0; i < 4; i++) {
			int tx = dx[i] + p.first.first, ty = dy[i] + p.first.second;
			if (tx <= 0 || tx > n || ty <= 0 || ty > n 
			    || visited[tx][ty] || g1[tx][ty] == 'Y') continue;
			q.push(make_pair(make_pair(tx, ty), p.second + 1));
		}
	}
}

