    for(i=0;i<v[s].size();i++){
        k=v[s][i];
        if(left[k]==-1){
            left[k]=s;
            right[s]=i;
            return true;
        }
        else if(dfs(left[k])){
            left[k]=s;
            right[s]=i;
            return true;
        }
    }

    return false;

}


