void addedge(int u,int v,int w)
{
	edge[cnt].to=v;
	edge[cnt].w=w;
	edge[cnt].next=head[u];
	head[u]=cnt++;
	edge[cnt].to=u;
	edge[cnt].w=0;//反向边边权设置为0
	edge[cnt].next=head[v];
	head[v]=cnt++;
}

int d[N],now[N];//深度 当前弧优化

bool bfs(int s,int t)//寻找增广路
{
	memset(d,0,sizeof(d));
	queue<int>q;
	q.push(s);
	now[s]=head[s];
	d[s]=1;
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		for(int i=head[u];i!=-1;i=edge[i].next)
		{
			int v=edge[i].to;
			int w=edge[i].w;
			if(d[v])
				continue;
			if(!w)
				continue;
			d[v]=d[u]+1;
			now[v]=head[v];
			q.push(v);
			if(v==t)
				return true;
		}
	}
	return false;
}

int dinic(int x,int t,int flow)//更新答案
{
	if(x==t)
		return flow;
	int rest=flow,i;
	for(i=now[x];i!=-1&&rest;i=edge[i].next)
	{
		int v=edge[i].to;
		int w=edge[i].w;
		if(w&&d[v]==d[x]+1)
		{
			int k=dinic(v,t,min(rest,w));
			if(!k)
				d[v]=0;
			edge[i].w-=k;
			edge[i^1].w+=k;
			rest-=k;
		}
	}
	now[x]=i;
	return flow-rest;
}

int solve(int st,int ed)
{
	int ans=0,flow;
	while(bfs(st,ed))
		while(flow=dinic(st,ed,inf))
			ans+=flow;
	return ans;
}

int get_id(int x,int y,int k)//science:0 capsule:1
{
	return (x-1)*n+y+k*n*n;
}

void dfs(int x,int y,int xx,int yy,int step)
{
	vis[xx][yy]=true;
	dp[step][x][y][xx][yy]=true;
	if(step>=t||maze[step][xx][yy])
		return;
	for(int k=0;k<4;k++)
	{
		int nx=xx+b[k][0];
		int ny=yy+b[k][1];
		if(nx<=0||ny<=0||nx>n||ny>n)
			continue;
		if(vis[nx][ny])
			continue;
		if(maze[step][nx][ny])
			continue; 
		dfs(x,y,nx,ny,step+1);
	}
}

