struct edge
{
  int to, c, f, rev;
  edge() {}
  edge(int too, int cc, int ff, int revv)
  {
    to = too;
    c = cc;
    f = ff;
    rev = revv;
  }
};

vector <edge> g[SIZE];
int d[SIZE], ptr[SIZE], s, t, n;
queue <int> q;

void addEdge(int v, int u, int cap)
{
  g[v].pb(edge(u, cap, 0, 0));
  g[u].pb(edge(v, 0, 0, 0));
  g[v].back().rev = g[u].size() - 1;
  g[u].back().rev = g[v].size() - 1;
}
bool buildLevNet()
{
  for (int i = 0; i <= t; ++i)
    d[i] = INF;
  d[s] = 0;
  q.push(s);
  while (!q.empty())
  {
    int v = q.front();
    q.pop();
    for (int i = 0; i < g[v].size(); ++i)
    {
      int to = g[v][i].to;
      int cf = g[v][i].c - g[v][i].f;
      if (d[to] == INF && cf > 0)
      {
        d[to] = d[v] + 1;
        q.push(to);
      }
    }
  }
  return d[t] != INF;
}

int dfs(int v, int curFlow)
{
  if (v == t) return curFlow;
  for (int& i = ptr[v]; i < g[v].size(); ++i)
  {
    int to = g[v][i].to;
    int cf = g[v][i].c - g[v][i].f, addFlow;
    if (d[to] == d[v] + 1 && cf > 0 && (addFlow = dfs(to, min(curFlow, cf))))
    {
      g[v][i].f += addFlow;
      g[to][g[v][i].rev].f -= addFlow;
      return addFlow;
    }
  }
  return 0;
}

int dinica()
{
  int flow = 0;
  while (buildLevNet())
  {
    memset(ptr, 0, sizeof(ptr));
    int add;
    while ((add = dfs(s, INF)))
      flow += add;
  }
  return flow;
}



