            }
        }
    }

}
inline bool bfs()
{
    memset(di,-1,n * sizeof di[0]);
    int qh = 0 , qt = 0;
    q[qt ++] = source;
    di[source] = 0;
    while (qh < qt && di[sink] == -1)
    {
        int v = q[qh ++];
        for (int pt = 0 ; pt < g[v].size() ; pt ++)
        {
            int id = g[v][pt] , to = e[id].b;
            if (di[to] == -1 && e[id].flow < e[id].cap)
            {
                q[qt ++] = to;
                di[to] = di[v] + 1;
            }
        }
    }
    return di[sink] != -1;
}
inline int dfs(int v , int flow)
{
    if (!flow) return 0;
    if (v == sink) return flow;
    for ( ; ptr[v] < g[v].size() ; ptr[v] ++)
    {
        int id = g[v][ptr[v]] , to = e[id].b;
        if (di[to ] != di[v] + 1) continue;
        int pushed = dfs(to , min(flow , e[id].cap - e[id].flow));
        if (pushed)
        {
            e[id].flow += pushed;
            e[id^1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}
inline int max_flow()
{
    int flow = 0;
    while (true)
    {
        if (!bfs()) break;
        memset(ptr,0,n * sizeof ptr[0]);
        while (int pushed = dfs(source , 1e9))
        {
            flow += pushed;
        }
    }
    return flow;
}
