void search(int x,int z)
{
  if(x==n+1)
  {
    p=z;
    flag=true;
    return;
  }
  int temp=n+2;
  for(int y=0;y<=n+1;++y)
  {
    if(d[x][y]<f[x][y])
    {
      temp=min(temp,h[y]);
      if(h[x]==h[y]+1)
      {
        w[++tot]=y;
        search(y,min(z,f[x][y]-d[x][y]));
        if((!t)||(flag))
          return;
        w[tot--]=0;
      }
    }
    if(d[y][x]>0)
    {
      temp=min(temp,h[y]);
      if(h[x]==h[y]+1)
      {
        w[++tot]=-y;
        search(y,min(z,d[y][x]));
        if((!t)||(flag))
          return;
        w[tot--]=0;
      }
    }
  }
  if(temp+1!=h[x])
  {
    --g[h[x]];
    if(g[h[x]]==0)
      t=false;
    h[x]=temp+1;
    ++g[h[x]];
  }
}

bool improvable()
{
  flag=false;
  p=n1;
  tot=0;
  w[0]=0;
  search(0,n1);
  return flag;
}

void improve()
{
  for(int x=1;x<=tot;++x)
  {
    if(w[x]>0)
      d[abs(w[x-1])][w[x]]+=p;
    else
      d[-w[x]][abs(w[x-1])]-=p;
  }
}

