        s = 0, t = 2*cnt + 1;
        for( int i = 0; i < n; ++i )
                for( int j = 0; j < n; ++j ) if( inside( i, j ) ) {
                        bfs( i, j );
                }

        cout<<maxFlow()<<endl;
}

