ll x, y, n, mna = -1, mnb = -1;

void calc (ll a, int b){
  if (a < 0){
    return;
  }
  if (mna == -1){
    mna = a;
    mnb = b;
    return;
  }
  if (abs(mnb * x - mna * y) * b > abs(b * x - a * y) * mnb){
    mnb = b, mna = a;
  }
  else if ((abs(mnb * x - mna * y) * b == abs(b * x - a * y) * mnb) && (b < mnb || (b == mnb && a < mna))){
    mna = a, mnb = b;
  }
}

int main (){
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cin >> x >> y >> n;
  ll a;
  for (int i = 1; i <= n; ++i){
    ll cur = i * x / y;
    a = cur - 1;
    calc(a, i);
    a = cur;
    calc(a, i);
    a = cur + 1;
    calc(a, i);
  }
  cout << mna << "/" << mnb;
  return 0;
}

