        return 0;
    }
    if (x==y){
        cout << "1/1";
        return 0;
    }

    double ans=1e18;
    double xy=double(x)/double(y);
    long long ansx,ansy;
    long long l=0,r=y;
    for (long long i=1;i<=n;i++){
        while (i*x>r){l+=y;r+=y;}
        if (i*x>=l && i*x<=r) {
            long long ll=l/y;
            long long rr=r/y;
            double li=double(ll)/double(i);
            double ri=double(rr)/double(i);
            double tmp1=abs(xy-li);
