long long n, x, y;
long long gcd(long long a, long long b)
{
	while(b)
	{
		a %= b;
		swap(a,b);
	}
	return a;
}
struct dro
{
	long long ch;
	long long zn;
	dro()
	{}
	dro(long long a, long long b)
	{
		ch = a;
		zn = b;
	}
	void operator - (const dro &a)
	{
		ch = ch * a.zn - a.ch * zn;
		zn = zn * a.zn;
	}
	bool operator < (const dro &a) const
	{
		if (ch * a.zn < a.ch * zn)
			return true;
		else
			return false;
	}
	void cok()
	{
		long long j = gcd(ch, zn);
		ch /= j;
		zn /= j;
	}
	void sho()
	{
		cout << ch << "/" << zn;
	}
};

int main ()
{
	//freopen("input.txt", "r", stdin);
	cin >> x >> y >> n;
	dro os(50, 1);
	dro na(x, y), ot;
	for (long long i = 1; i <= n; ++i)
	{
		dro p;
		long long r = (na.ch * i) / na.zn;
		long long z = (na.ch * i) % na.zn;
		if (z > (na.zn / 2))
			r++, z = na.zn - z;
		p.ch = z;
		p.zn = i * na.zn;
		if (p < os)
		{	
			os = p;
			ot.ch = r;
			ot.zn = i;
		}
	}
	ot.sho();
}

