int gcd (int x, int y)
{
    int gcd;
    if (x > y)
        gcd = x;
    else
        gcd = y;

    while (true)
    {
        if (x%gcd == 0 && y%gcd == 0)
            break;
        gcd--;
    }
    return gcd;
}

