LL process(LL n){
 //   cout<<n<<endl;          
    if(n <= 6){
        return n;
    }
    if(n <= 11) return (13 - n);
    LL tmp = find(n);
    LL more = tmp*10+1;
    if(n % tmp == 0){
         LL t = n / tmp;
         if(n <= more/2 + tmp) return num(tmp)*t;
         else{
              LL cur = process(more - n);
              return num(more) + cur;
         }
    }
    else{
        LL _m = (n / tmp)*tmp;
        LL _M = (n / tmp + 1)*tmp;
        LL res = process(_m) + process(n - _m);
        if(n > more/2) res = min(process(_m) + process(n - _m), num(more) + process(more-n));
        return res;
    }
}
