ll nod(ll a, ll b) {
    if(b > a) {
		swap(a, b);
	}
    while(b > 0) {
	    a %= b;
		swap(a, b);
    }
	return a;
}
ll nok(ll a,ll b) {
    return a * b / nod(a, b);
}
