int dfs(BS &x){
	if(id.find(x) != id.end()) return id[x];
	int nd = id[x] = ++cnt; BS tmp[7] , tp;
	for(int i = 0 ; i < N ; ++i) for(int j = 0 ; j < 1 << N ; ++j) tmp[i][j | (1 << i)] = tmp[i][j | (1 << i)] | x[j];
	for(int i = 0 ; i < 1 << N ; ++i){
		tp = x; for(int j = 0 ; j < N ; ++j) if(i >> j & 1) tp |= tmp[j];
		trans[nd][i] = dfs(tp); 
	}
	return nd;
}

