	x -= y;
	return (x<0 ? x+MOD : x);
}
ll mult(ll x, ll y) {
	return (x * y) % MOD;
}
ll modpow(ll x, ll p) {
	if (p == 0) return 1;
	if (p & 1) return mult(x, modpow(x, p - 1));
	return modpow(mult(x, x), p>>1);
}
