matrix get(ll n , int ind)
{
	if(!n)
		return matrix(k + 1 , 1);

	for(int i = ind; i >= 0; i--)
		if(n >= val[i])
		{
			matrix tmp = get(n % val[i] , i - 1);
			int x = n / val[i];

			matrix ans = a[i];
			for(int j = 1; j < x; j++)
			{
				ans = ans * shift[k - 1];
				ans = ans * a[i];
			}
			ans = ans * shift[k - 1];
			ans = ans * tmp;
			ans = ans * shift[x - 1];
			return ans;
		}

	cout << 1/0 << endl;
	return matrix(k + 1 , -800);
}

