mat mat_mul(mat a, mat b)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			res[i][j] = 0;
			FOR(k, 0, K + 1)
			{
				res[i][j] += a[i][k] * b[k][j];
				res[i][j] %= INF;
			}
		}
	}
	return res;
}
mat shift(mat a, int x)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			if (a[i][j] == 0) continue;
			if (i == j) res[i][j] = a[i][j];
			else res[i][(j + x) % K] = a[i][j];
		}
	}
	return res;
}

