	matrix operator *(const matrix &B)const{
		matrix C; C.N = N; 
		for(int i = 0 ; i <= N ; ++i)
			for(int j = 0 ; j <= N ; ++j){
				C.A[i][j] = 0;
				for(int k = 0 ; k <= N ; ++k)
					C.A[i][j] = ((LL)A[i][k]*B.A[k][j] + C.A[i][j])%MOD;
			}
		return C;
	}
}A[64][30],sum[64][30],suf[64][30],ans;

LL N,K,dig[70],cnt;

int main(){
	scanf("%lld%lld",&N,&K);
	while(N){dig[cnt++] = N % K; N /= K;}
	for(int i = 0 ; i < K ; ++i){
		for(int j = 0 ; j <= K ; ++j)
			A[0][i].A[j][j] = 1,A[0][i].A[j][i] = 1;
		A[0][i].N = K;
	}
	sum[0][0] = A[0][0]; suf[0][K-1] = A[0][K-1];
	for(int i = 1 ; i < K ; ++i) sum[0][i] = sum[0][i-1]*A[0][i];
	for(int i = K - 2; ~i ; --i) suf[0][i] = A[0][i]*suf[0][i+1];
	for(int i = 1 ; i < cnt ; ++i){
		A[i][0] = suf[i-1][0];
		for(int j = 1 ; j < K ; ++j)
			A[i][j] = suf[i-1][j]*sum[i-1][j-1];
		sum[i][0] = A[i][0]; suf[i][K-1] = A[i][K-1];
		for(int j = 1 ; j < K ; ++j) sum[i][j] = sum[i][j-1]*A[i][j];
		for(int j = K - 2 ; ~j; --j) suf[i][j] = A[i][j]*suf[i][j+1];
	}
	ans.A[0][K] = 1; ans.N = K;
	ans = ans*sum[cnt-1][dig[cnt-1] - 1];
	int last = dig[cnt-1];
	for(int i = cnt - 2 ; ~i ; --i){
		for(int j = 0 ; j < dig[i] ; ++j)	
			ans = ans*A[i][(j+last)%K];
		last += dig[i];
	}
	LL res = 0;
	for(int i = 0 ; i <= K ; ++i) res = res + ans.A[0][i];
	printf("%lld\n",res%MOD);
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100, D = 31, MOD = 1E9 + 7;

int d, cur, a[N];
long long n;

struct matrix {
    long long f[D][D];

    matrix() {
        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                f[i][j] = 0;
            }
        }
    }

    matrix operator*(const matrix& oth) const {
        matrix ans;
        for (int i = 0; i <= d; i++) {
            for (int j = 0; j <= d; j++) {
                for (int k = 0; k <= d; k++) {
                    (ans.f[i][j] += f[i][k] * oth.f[k][j]) %= MOD;
                }
            }
        }
        return ans;
    }
} bas[N];

matrix rotate(int u) {
    (u += d) %= d;
    matrix ans;
    for (int i = 0; i < d; i++) {
        ans.f[i][(i + u) % d] = 1;
    }
    ans.f[d][d] = 1;
    return ans;
}

void init() {
    for (int i = 1; i < d; i++) {
        bas[0].f[i][i] = 1;
    }
    bas[0].f[d][0] = 1;
    bas[0].f[d][d] = 2; bas[0].f[0][d] = -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> d;
    for (cur = 0; n > 0; cur++, n /= d) {
        a[cur] = n % d;
    }
    init();
    for (int i = 1; i < cur; i++) {
        bas[i] = rotate(0);
        for (int j = 0; j < d; j++) {
            bas[i] = bas[i] * bas[i - 1] * rotate(1);
        }
    }
    matrix ans = rotate(0);
    for (int i = cur - 1; i >= 0; i--) {
        for (int j = 0; j < a[i]; j++) {
            ans = ans * bas[i] * rotate(1);
        }
    }
    cout << (ans.f[d][d] + MOD) % MOD;
}

