      m3.a[i][j] = 0;
      for (int l = 0; l < k; l++) {
    m3.a[i][j] += (m1.a[i][l] * m2.a[l][j]) % MOD;
      }
      m3.a[i][j] %= MOD;
    }
  }
  return m3;
}

vec mult (mat m, vec v) {
  vec v2;
  for (int i = 0; i < k; i++) {
    v2.a[i] = 0;
    for (int j = 0; j < k; j++) {
      v2.a[i] += (v.a[j] * m.a[i][j]) % MOD;
    }
    v2.a[i] %= MOD;
  }
  return v2;
}

