lld N; int K;

struct MAT{
  int m[31][31];
  MAT operator * (const MAT &ot)const{
    MAT ret = {0, };
    for (int i=0;i<=K;i++) {
      for (int j=0;j<=K;j++) {
        ret.m[i][j] = 0;
        for (int k=0;k<=K;k++)
          ret.m[i][j] = (ret.m[i][j]+(lld)m[i][k]*ot.m[k][j])%MOD;
      }
    } return ret;
  }
} A[65][30], P[65][30], S[65][30], res;

int main() {
