      A[0][i].a[j][j] = 1;
      A[0][i].a[j][i] = 1;
    }
  }
  for (int m = 1; pow(k, m) - 1000 <= n; ++m) {
    pre_calc(m - 1);
    REP (x, k) {
      A[m][x] = suffix[m - 1][x];
      if (x > 0) {
        A[m][x].mul(prefix[m - 1][x]);
      }
    }
  }
  Matrix mat = solve(n, 0);
  int ans = 0;
  REP (i, k + 1) {
    (ans += mat.a[k][i]) %= MOD;
  }
  cout << ans << endl;
  return 0;
}

