    b[1] = calc(k-1, k);
    c[1] = matpow(b[1],k-1);
    Matrix<ll> s = unit<ll>(2*k+1);
    REP(j,2,cnt+2){
        b[j] = calc(k-j%k, k);
        s *= c[j-1];
        b[j] *= s;
        c[j] = matpow(b[j],k-1);
    }
    int idx = 1;
    int rem = n%k;
    n-=rem;
    int q = 0;
    tmp = n;
    if(tmp){while(tmp%k==0){
        ++q;
        tmp/=k;
    }
    }
    q=(k-q%k)%k;
    Matrix<ll> ans = unit<ll>(2*k+1);
    ans = matpow(a[q],rem)*matpow(a[q+k],max(rem-q,0));
    n/=k;
    if(!n){
        return (ans.get(2*k,0)+ans.get(0,0))%mod;
    }
    --n;
    while(n){
        ll t = n%k;
        if(t){
            ans *= matpow(b[idx],t);
        }
        n/=k;
        ++idx;
    }
    ans *= b[1];

    return (ans.get(2*k,0)+ans.get(0,0))%mod;
}
