int n,k,p;
int fpow(int a,int b)
{
	int ans=1,t=a;
	while(b)
	{
		if(b&1)ans=1ll*ans*t%p;
		t=1ll*t*t%p;b>>=1;
	}
	return ans;
}
int lowbit(int x)
{
	return x&(-x);
}
int f[26][250010];
int fac[250010],inv[250010];
void init()
{
	fac[0]=1;
	for(int i=1;i<=n;i++)
		fac[i]=1ll*fac[i-1]*i%p;
	inv[n]=fpow(fac[n],p-2);
	for(int i=n;i>=1;i--)
		inv[i-1]=1ll*inv[i]*i%p;
	return ;
}
int solve(int cur,int S)
{
	if(f[cur][S]!=-1)
		return f[cur][S];
	if(!S){
		f[cur][S]=fac[n];
		for(int i=1;i<=cur;i++)
			f[cur][S]=1ll*f[cur][S]*(k-i+1)%p;
		return f[cur][S];
	}
	f[cur][S]=0;
	int U=S-lowbit(S);
	for(int T=U;T;T=(T-1)&U)
		f[cur][S]=(f[cur][S]+1ll*inv[S-T]*solve(cur+1,T))%p;
	f[cur][S]=(f[cur][S]+1ll*inv[S]*solve(cur+1,0))%p;
	return f[cur][S];
}
