	for(int i=1;i<=n;i++)
		ans=1ll*ans*k%p;
	if(n%2==0){
		init();
		memset(f,-1,sizeof(f));
		ans=(ans-solve(0,n)+p)%p;
	}
	printf("%d\n",ans);
	return 0;
}

