long long fast_pow(long long x, long long y)
{
    long long ans = 1, now = x;
    while (y)
    {
        if (y & 1) ans = ans * now % p;
        now = now * now % p;
        y >>= 1;
    }
    return ans;
}
void init(void)
{
    fac[0] = 1;
    for (int i = 1; i <= maxi; i++)
        fac[i] = fac[i - 1] * i % p;
    inv[maxi] = fast_pow(fac[maxi], p - 2);
    for (int i = maxi - 1; i >= 0; i--)
        inv[i] = inv[i + 1] * (i + 1) % p;
}
int lower(int x)
{
    int tmp = 1;
    for (; tmp < x; tmp <<= 1);
    return tmp;
}
void FWT(int *now, int len, bool type = false)
{
    long long *T = t[0];
    for (int i = 0; i < len; i ++) T[i] = now[i];
    if (type)
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    T[i + k] -= T[k];
    else
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    T[i + k] += T[k];
    for (int i = 0; i < len; i ++) {
        now[i] = T[i] % p;
        if (now[i] < 0) now[i] += p;
    }
}
