            g[n][i] += rfact[l] * g[n ^ l][i - 1];
            if (cnt >= 8) {
                g[n][i] %= p;
            }
        }
        if (cnt >= 8)
            cnt = 0;
        return;
    }
    solve(n, bit, k + 1, l);
    solve(n, bit, k + 1, l ^ (1 << bit[k]));
}

