    return { a.first * b.first,a.second * b.first + a.first * b.second };
}
mP plu(mP a, mP b) {
    return { a.first + b.first,a.second + b.second };
}


mP dp[501];
bool used[501];
void init() {
    init_f();
    dp[0] = { 1,0 };
    dp[1] = { 2,0 };
    for (int n = 2; n <= 500; n++) {
        rep(j, n) {
            modint cnt = n + 1; modint sum = 0;
            rep(k, n)sum += abs(j - k);
            mP cl = dp[j];
            mP cr = dp[n - 1 - j];
            mP x = mul(cl, cr);
            x.first *= comb(n - 1, j);
            x.second *= comb(n - 1, j);
            x = mul(x, { cnt,sum });
            dp[n] = plu(dp[n], x);
        }
    }
}

mP dp2[502][501];
void solve() {
    int n, m; cin >> n >> m >> mod;
    init();
    dp2[0][0] = { 1,0 };
    rep(i, n) {
        rep(k, i + 1) {
            for (int j = i; j < n; j++) {
                int ni = j + 2; ni = min(ni, n);
                int nk = k + j - i + 1;
                if (nk <= m) {
                    mP x = mul(dp2[i][k], dp[j - i + 1]);
                    x.first *= comb(nk, k);
                    x.second *= comb(nk, k);
                    dp2[ni][nk] = plu(dp2[ni][nk], x);
                }
            }
            dp2[i + 1][k] = plu(dp2[i + 1][k], dp2[i][k]);
        }
    }
    modint ans = dp2[n][m].second;
    cout << ans << "\n";
}

