                // dp[l][i] -> dp[r][i + di]
                mint z = dp[l][i].first * f[di].first;
                dp[r][i + di].first += z * C[i + di][di];
                dp[r][i + di].second += (dp[l][i].second * f[di].first + dp[l][i].first * f[di].second) * C[i + di][di];
            }
        }
    }

    dbg(dp[n + 1][m].first.val(), dp[n + 1][m].second.val());

    pr.writeln(dp[n + 1][m].second.val());
