			for(int k = 0 ; k + i + 1 <= N + 1 && k + j <= M ; ++k){
				dp[i + k + 1][j + k] = (dp[i + k + 1][j + k] + 1ll * dp[i][j] * C[M - j][k] % P * num[k]) % P;
				ans[i + k + 1][j + k] = (ans[i + k + 1][j + k] + 1ll * ans[i][j] * C[M - j][k] % P * num[k] + 1ll * dp[i][j] * C[M - j][k] % P * V[k]) % P;
			}
	cout << ans[N + 1][M]; return 0;
}

