namespace Main {

	struct Solution: Data {

		ll pw(ll x, ll y) {
			ll res = 1;
			while (y) {
				if (y & 1) {
					res = res * x % mod;
				}
				x = x * x % mod;
				y >>= 1;
			}
			return res;
		}

		ll inv(ll x) {
			return pw(x, mod - 2);
		}

		ll ss(int x) {
			return x * (x + 1) / 2;
		}

		ll c[N + 1][N + 1];

		// cnt, sum
		pll a[N + 1];
		pll d[N + 2][N + 1];

		void solve() {
			forn (i, n + 1) {
				forn (j, n + 1) {
					if (!i || !j) {
						c[i][j] = 1;
						continue;
					}
					c[i][j] = (c[i - 1][j] + c[i][j - 1]) % mod;
				}
			}

			memset(a, 0, sizeof a);
			a[0] = pll(1, 0);
			forn (i, 1, m + 1) {
				forn (j, i) {
					pll cur;
					cur.fs = a[j].fs * a[i - 1 - j].fs % mod;
					cur.sc = (a[j].sc * a[i - 1 - j].fs + a[j].fs * a[i - 1 - j].sc) % mod;
					cur.sc = (cur.sc * (i + 1) + (ss(j) + ss(i - 1 - j)) * cur.fs) % mod;
					cur.fs = cur.fs * (i + 1) % mod;
					cur.fs = cur.fs * c[j][i - 1 - j] % mod;
					cur.sc = cur.sc * c[j][i - 1 - j] % mod;
					a[i].fs = (a[i].fs + cur.fs) % mod;
					a[i].sc = (a[i].sc + cur.sc) % mod;
				}
			}

			debug(a, a + m + 1);

			memset(d, 0, sizeof d);
